"""
Shared helpers for Whisper / Qwen island (windowed VAD) ASR paths.

Keep backend-specific infer in adapters; use these for temp dirs + cancel checks.
"""

from __future__ import annotations

import shutil
import tempfile
from pathlib import Path
from typing import Callable


def make_island_workdir(prefix: str) -> Path:
    """Create a unique temp directory for one island batch (caller must cleanup)."""
    return Path(tempfile.mkdtemp(prefix=prefix))


def cleanup_island_workdir(work: Path | None) -> None:
    if not work:
        return
    try:
        shutil.rmtree(work, ignore_errors=True)
    except Exception:
        pass


def raise_if_island_cancelled(should_cancel: Callable[[], bool] | None) -> None:
    if should_cancel and should_cancel():
        raise RuntimeError("cancelled")
